add_action( 'woocommerce_before_checkout_form', 'perfectpixel_cart_on_checkout', 5 );
add_filter( 'woocommerce_get_cart_url', 'perfectpixel_cart_url_to_checkout' );
add_filter( 'woocommerce_checkout_redirect_empty_cart', '__return_false' );
add_filter( 'woocommerce_checkout_update_order_review_expired', '__return_false' );
add_action( 'wp_head', 'perfectpixel_cart_on_checkout_css' );

function perfectpixel_cart_on_checkout() {
	if ( is_wc_endpoint_url() ) {
		return;
	}
	echo do_shortcode( '[woocommerce_cart]' );
}

function perfectpixel_cart_url_to_checkout( $url ) {
	return wc_get_checkout_url();
}

// The cart totals and "Proceed to checkout" button are not needed on the checkout itself.
function perfectpixel_cart_on_checkout_css() {
	if ( function_exists( 'is_checkout' ) && is_checkout() ) {
		echo '<style>.woocommerce-checkout .cart-collaterals{display:none}</style>';
	}
}
